def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    color_map = {3: 8, 8: 7, 7: 6, 6: 3}
    # Each 2x2 block of 2s is surrounded at its diagonal corners by markers.
    for r in range(h - 1):
        for c in range(w - 1):
            if grid[r][c] == grid[r][c + 1] == grid[r + 1][c] == grid[r + 1][c + 1] == 2:
                corners = [
                    (r - 1, c - 1, -1, -1),
                    (r - 1, c + 2, -1, 1),
                    (r + 2, c - 1, 1, -1),
                    (r + 2, c + 2, 1, 1),
                ]
                for sr, sc, dr, dc in corners:
                    if 0 <= sr < h and 0 <= sc < w and grid[sr][sc] in color_map:
                        color = color_map[grid[sr][sc]]
                        rr, cc = sr, sc
                        while 0 <= rr < h and 0 <= cc < w:
                            out[rr][cc] = color
                            rr += dr
                            cc += dc
    return out

